BEGIN READ ONLY; SET LOCAL statement_timeout = '10s'; SELECT jsonb_build_object('captured_at',now(),'extensions',(SELECT jsonb_agg(jsonb_build_object('name',extname,'version',extversion) ORDER BY extname) FROM pg_extension),'indexes',(SELECT jsonb_agg(jsonb_build_object('schema',s.schemaname,'table',s.relname,'index',s.indexrelname,'definition_md5',md5(pg_get_indexdef(s.indexrelid)),'bytes',pg_relation_size(s.indexrelid),'scans',s.idx_scan,'tuples_read',s.idx_tup_read,'tuples_fetched',s.idx_tup_fetch) ORDER BY s.schemaname,s.relname,s.indexrelname) FROM pg_stat_user_indexes s WHERE s.schemaname IN ('public','private')),'blocked_sessions',(SELECT count(*) FROM pg_stat_activity WHERE datname=current_database() AND cardinality(pg_blocking_pids(pid))>0)) AS baseline_indexes; COMMIT;
